import { JSON } from "../..";
import { expect } from "../../__tests__/lib";
import { bench, blackbox, dumpToFile } from "../lib/bench";
import {
  GrowingObject,
  OBJECT_SIZES,
  OBJECT_LABELS,
  makeObjectJson,
} from "./object-workload";

let input = "";
let value = new GrowingObject();
let dynamic = new JSON.Obj();

function nativeOperation(): void {
  const start = changetype<usize>(input);
  const end = start + (input.length << 1);
  let next: usize = 0;
  // @ts-ignore: generated by the transform
  if (isDefined(value.__DESERIALIZE_FAST)) {
    // @ts-ignore: generated by the transform
    next = value.__DESERIALIZE_FAST(start, end, value);
  } else {
    // @ts-ignore: generated by the transform
    next = value.__DESERIALIZE_SLOW(start, end, value);
  }
  if (next != end)
    throw new Error("Growing-object reader did not consume its input");
  blackbox(value);
}

function dynamicOperation(): void {
  blackbox(JSON.parse<JSON.Obj>(input));
}

for (let i = 0; i < OBJECT_SIZES.length; i++) {
  input = makeObjectJson(OBJECT_SIZES[i]);
  const bytes = String.UTF8.byteLength(input);
  const operations = min<i32>(200000, max<i32>(5, (500 * 1024 * 1024) / bytes));
  const label = OBJECT_LABELS[i];
  value = JSON.parse<GrowingObject>(input);
  dynamic = JSON.parse<JSON.Obj>(input);
  expect(JSON.stringify(value)).toBe(input);
  nativeOperation();
  expect(JSON.stringify(value)).toBe(input);
  bench(
    "Deserialize Object (" + label + ")",
    nativeOperation,
    operations,
    bytes,
  );
  dumpToFile("obj-" + label, "deserialize");
  bench(
    "Deserialize Object JSON.Obj (" + label + ")",
    dynamicOperation,
    operations,
    bytes,
  );
  dumpToFile("obj-" + label + "-obj", "deserialize");
}
